const openProgressLogs=new Set();
let toastTimer,pollTimer,runtimeTimer,cameraTimer,driveTimer,driveSending=false,cameraBusy=false,droneUrl=null,drag=null,deviceTouched=false,scenePromise=null;
const wb=p=>'/api/workbench'+p;
const admin=p=>`/api/admin/${S.runtime==='mission'?'':S.runtime+'/'}${p}`;
const robot=p=>`/sim/${S.runtime==='mission'?'':S.runtime+'/'}robot/${p}`;
const fmt=(v,d=2)=>Number.isFinite(Number(v))?Number(v).toFixed(d):'—';
const percent=v=>v==null?'—':`${fmt(Number(v)*100,1)}%`;
function flash(message,error=false){$('#toast').textContent=message;$('#toast').classList.toggle('error',error);$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,error?8000:4000)}
function detailError(data,status){const value=data?.detail||data?.error||data?.message;return typeof value==='string'?value:Array.isArray(value)?value.map(x=>x.msg||String(x)).join(' · '):`서버 오류 ${status}`}
async function response(path,{method='GET',body,signal,auth=true}={}){const headers={};if(auth&&S.key)headers['X-Admin-Key']=S.key;if(body!==undefined)headers['Content-Type']='application/json';const r=await fetch(path,{method,headers,body:body===undefined?undefined:JSON.stringify(body),cache:'no-store',signal:signal||AbortSignal.timeout(15000)});if(!r.ok){let data;try{data=await r.json()}catch{}const error=new Error(detailError(data,r.status));error.status=r.status;throw error;}return r}
async function api(path,opts){return (await response(path,opts)).json()}
async function imageURL(path){if(S.urls.has(path))return S.urls.get(path);const blob=await (await response(path)).blob();const url=URL.createObjectURL(blob);S.urls.set(path,url);return url}
async function act(name,button,work){if(S.busy.has(name))return;S.busy.add(name);if(button)button.disabled=true;renderAvailability();try{await work();await refreshStatus()}catch(e){flash(e.message,true)}finally{S.busy.delete(name);if(button)button.disabled=false;renderAvailability()}}
function setConnection(ok,error){S.connected=ok;$('#server-dot').className=`status-dot ${ok?'online':'offline'}`;$('#server-state').textContent=ok?'로컬 서버 연결됨':'서버 연결 끊김';$('#connection-error').hidden=ok;$('#connection-error').textContent=error||'서버 상태를 읽지 못했습니다. 마지막 확인 상태를 유지하고 다시 연결합니다.'}
async function initialize(key){if(key)S.key=key;else{try{const c=await api('/api/config',{auth:false});S.key=c.admin_key;S.teams=c.teams||[]}catch(e){setConnection(false,'자동 접속 정보가 없습니다. 운영자 키로 연결하세요.');$('#access-dialog').showModal();return;}}clearTimeout(pollTimer);pollStatus();runtimeLoop();cameraLoop()}
async function refreshStatus(){const status=await api(wb('/status'));S.summary=status;S.physics=status.physics||status.capabilities?.physics||null;if(!S.runtimeInitialized&&['practice','mission','rehearsal'].includes(S.physics?.runtime)){S.runtime=S.physics.runtime;S.runtimeInitialized=true;$('#runtime-mode').value=S.runtime;}setConnection(true);renderStatus(status);recording?.update();return status}
async function pollStatus(){try{await refreshStatus()}catch(e){setConnection(false,e.message);renderAvailability()}pollTimer=setTimeout(pollStatus,S.connected?1200:2500)}
function labelForStatus(status){return statusNames[status]||status||'확인 전'}
function statusClass(status){return ['succeeded','ready','observing'].includes(status)?'good':['failed','interrupted'].includes(status)?'bad':['running','starting','loading','queued','cancelling'].includes(status)?'warn':''}
function physicsReady(){return !!(S.physics?.connected&&S.physics.runtime===S.runtime)}
function switchPage(page,updateURL=true){if(!['develop','data','train','evaluate','deploy','run','equipment'].includes(page))page='develop';S.page=page;recording?.onPage(page);if(updateURL){const url=new URL(location.href);url.searchParams.set('page',page);history.replaceState(null,'',url);}$$('[data-page]').forEach(el=>el.classList.toggle('active',el.dataset.page===page));$$('[data-workspace-page]').forEach(el=>{el.hidden=el.dataset.workspacePage!==page;el.classList.toggle('active',!el.hidden)});if(page==='run'){ensureScene();S.scene?.resize();refreshRuntime();refreshCameras()}if(page==='evaluate'&&S.modelId)loadModel(S.modelId);if(page==='equipment')renderCapabilities();if(page==='develop'||page==='deploy')development?.enter();window.scrollTo({top:0,behavior:'instant'})}
function setOptions(id,items,placeholder,value){const select=$(id),sig=JSON.stringify(items);if(select.dataset.options!==sig){const old=value||select.value;select.innerHTML=`<option value="">${esc(placeholder)}</option>`+items.map(x=>`<option value="${esc(x.id)}">${esc(x.name||x.id)}</option>`).join('');select.value=items.some(x=>x.id===old)?old:'';select.dataset.options=sig;}}
function renderStatus(status){renderPhysics();renderCapabilities();const datasets=status.datasets||[],models=status.models||[];setOptions('#dataset-select',datasets,'데이터셋 선택',S.datasetId);for(const id of ['#train-dataset','#eval-dataset'])setOptions(id,datasets.filter(d=>d.frozen),'고정한 데이터셋 선택');for(const id of ['#eval-model','#deploy-model'])setOptions(id,models,'모델 선택',S.modelId);
  if(!S.datasetId&&datasets.length)loadDataset(datasets[0].id);if(!S.modelId&&models.length)selectModel(models[0].id);
  if(!S.selectionInitialized&&status.deployment){$('#deploy-mode').value=status.deployment.mode||'practice';$('#deploy-policy').value=status.deployment.policy||'observe';S.selectionInitialized=true}
  const model=models.find(m=>m.id===S.modelId);$('#sidebar-model').textContent=model?.name||'선택 안 됨';$('#sidebar-model-state').textContent=model?qualityText(model):'학습 후 선택할 수 있습니다.';
  const jobs=status.jobs||[];renderJobs(jobs);renderDeployment();renderController(status.controller||{});renderRunNotice();renderAvailability();development?.onStatus();
  const trainJob=jobs.find(j=>j.kind==='train');$('#train-job-status').textContent=trainJob?labelForStatus(trainJob.status):'작업 없음';$('#train-job-status').className=`tag ${statusClass(trainJob?.status)}`;if(trainJob)$('#train-progress').innerHTML=progressHTML(trainJob,true);
  const evalJob=jobs.find(j=>j.kind==='evaluate');$('#eval-progress').hidden=!evalJob;if(evalJob)$('#eval-progress').innerHTML=`<div class="progress-content">${progressHTML(evalJob,true)}</div>`;
  $('#trained-models').innerHTML=models.length?models.map(m=>`<button class="model-card" data-model="${esc(m.id)}"><strong>${esc(m.name||m.id)}</strong><span>${esc(m.id)}</span><small>시험 mAP50 ${percent(metricsFor(m).map50)} <span>${esc(qualityText(m))}</span></small></button>`).join(''):'<p class="muted">실제 학습이 완료되면 모델이 표시됩니다.</p>';
  const current=jobs.find(j=>j.id===S.jobId);if(current&&$('#job-dialog').open)renderJobDialog(current);
  const collected=jobs.find(j=>j.id===S.jobId&&j.kind==='collect'&&j.dataset_id);if(collected&&collected.dataset_id!==S.datasetId&&!S.dirty)loadDataset(collected.dataset_id);else if(S.dataset&&datasets.some(d=>d.id===S.datasetId&&(d.revision!==S.dataset.revision||d.count!==S.dataset.count||d.status!==S.dataset.status))&&!S.dirty)loadDataset(S.datasetId,S.frameIndex);if(model){const signature=JSON.stringify([model.metrics,model.per_class,model.quality,model.evaluation_jobs]);if(S.modelSignature!==signature){S.modelSignature=signature;loadModel(model.id);}}
  trainingOptions?.render(status);
}
function renderPhysics(){const p=S.physics||{},provider=p.provider||'물리 엔진';const ready=physicsReady();$('#physics-state').textContent=p.error?`${provider} · 연결 오류`:p.connected?`${provider} 연결됨${p.runtime!==S.runtime?' · 다른 실행 환경':''}`:p.running?`${provider} 시작 중`:p.installed?`${provider} 정지`:p.installed===false?'물리 엔진 설치 확인 필요':'상태 확인 중';$('#physics-detail').textContent=p.error||p.warning||[p.renderer?`렌더러 ${p.renderer}`:'',p.runtime?`환경 ${p.runtime}`:'',p.running&&p.frame_age_s!=null?`영상 지연 ${fmt(p.frame_age_s,1)}초`:''].filter(Boolean).join(' · ')||'실제 물리 엔진 연결 후 카메라를 사용할 수 있습니다.';$('#arena-source').textContent=ready?`${provider} · ${p.renderer||'물리 상태'}`:'물리 연결 없음';$('#arena-source').className=`tag ${ready?'good':'warn'}`;$('#arena-unavailable').hidden=ready&&!!S.scene;$('#world-time').textContent=`시뮬레이션 ${p.sim_time==null?'—':fmt(p.sim_time,1)+'초'}`;if(!ready){$('#sensor-freshness').textContent='현재 센서 연결 없음';$('#sensor-freshness').className='tag warn';$('#ugv-camera-empty').hidden=false;$('#ugv-camera-empty').textContent='선택한 환경의 물리 시뮬레이터를 연결하세요.';$('#drone-camera-empty').hidden=false;$('#drone-camera-empty').textContent='물리 카메라 연결 대기';}}
function capabilityText(value){if(value===true)return '사용 가능';if(value===false)return '사용 불가';if(value===null||value===undefined)return '확인 중';if(typeof value==='object')return value.status||value.version||JSON.stringify(value);return String(value)}
function renderCapabilities(){const c=S.summary?.capabilities||{},p=S.physics||{};const cards=[['Python',c.python],['PyTorch',c.torch],['Ultralytics',c.ultralytics],['Apple MPS',c.mps],['CPU',c.cpu],['물리 엔진',p.provider?`${p.provider} · ${p.connected?'연결됨':p.running?'시작 중':'정지'}`:c.physics?.provider]];const html=`<div class="capability-grid">${cards.map(([k,v])=>`<div class="capability"><span>${esc(k)}</span><strong>${esc(capabilityText(v))}</strong></div>`).join('')}</div>${c.error?`<p class="notice error">${esc(c.error)}</p>`:''}${p.error?`<p class="notice error">${esc(p.error)}</p>`:''}`;$('#health-content').innerHTML=html;$('#equipment-runtime').innerHTML=html;
  const devices=c.mps===true?[{id:'mps',name:'Apple GPU · MPS'},{id:'cpu',name:'CPU'}]:[{id:'cpu',name:c.status==='checking'?'CPU · 가속기 확인 중':'CPU'}];const select=$('#train-device');const old=select.value;const sig=JSON.stringify(devices);if(select.dataset.options!==sig){select.innerHTML=devices.map(d=>`<option value="${d.id}">${d.name}</option>`).join('');select.value=deviceTouched&&devices.some(d=>d.id===old)?old:c.mps===true?'mps':'cpu';select.dataset.options=sig;}
  $('#training-capability').textContent=c.status==='checking'?'PyTorch와 사용 가능한 장치를 확인하고 있습니다.':c.status==='unavailable'?`학습 환경을 확인하지 못했습니다. ${c.error||''}`:`PyTorch ${c.torch||'—'} · Ultralytics ${c.ultralytics||'—'} · ${c.mps===true?'Apple GPU 사용 가능':c.mps===false?'CPU 사용':'MPS 확인 중'}`;
}
function renderAvailability(){const busy=S.busy.size>0,ready=physicsReady(),c=S.summary?.capabilities||{},controller=S.summary?.controller||{},deployment=S.summary?.deployment;$('#physics-start').disabled=busy||!S.connected||S.physics?.installed===false||ready;$('#physics-start').textContent=S.busy.has('physics')?'경기장 연결 중…':ready?'물리 시뮬레이터 연결됨':'시뮬레이터 켜기';$('#physics-stop').disabled=!S.connected||stoppingSession;$('#session-stop').disabled=!S.connected||stoppingSession;$('#session-stop').textContent=stoppingSession?'정지 중…':'전체 정지';$('#physics-stop').textContent=stoppingSession?'정지 중…':'끄기';$('#collect-start').disabled=busy||!ready;$('#freeze-dataset').disabled=busy||!S.dataset||S.dataset.frozen||S.dataset.status!=='complete'||S.dirty;$('#train-start').disabled=busy||!$('#train-dataset').value||c.status!=='available';$('#eval-start').disabled=busy||!$('#eval-model').value||!$('#eval-dataset').value||c.status!=='available';$('#deploy-save').disabled=busy||!$('#deploy-model').value||controllerRunning(controller);const expected=deployment?.mode==='match'?'mission':deployment?.mode;$('#controller-start').disabled=busy||!deployment||!ready||expected!==S.runtime||controllerRunning(controller)||S.rosNotebook?.running||S.rosNotebook?.starting;$('#controller-stop').disabled=busy||!controllerRunning(controller);$('#save-labels').disabled=busy||!S.dirty||S.dataset?.frozen;$('#delete-box').disabled=busy||S.selectedBox<0||S.dataset?.frozen;$('#tool-draw').disabled=!!S.dataset?.frozen||S.dataset?.status!=='complete';$('#annotation-class').disabled=!!S.dataset?.frozen||S.dataset?.status!=='complete';const rosOwnsControl=!!(S.rosNotebook?.running||S.rosNotebook?.starting),canDrive=ready&&!rosOwnsControl&&(!controllerRunning(controller)||deployment?.policy==='observe');$$('[data-drive]').forEach(b=>b.disabled=!canDrive);$('#manual-help').textContent=rosOwnsControl?'ROS 실습에서 제어 중입니다. 실습 종료 후 이 화면에서 제어할 수 있습니다.':canDrive?'버튼을 누르는 동안 저속으로 움직입니다. 놓으면 정지합니다.':'관측 정책 또는 프로세스 정지 상태에서만 사용합니다.';for(const id of ['#gimbal-send','#fire-button'])$(id).disabled=busy||!canDrive;$('#oled-send').disabled=busy||!ready||rosOwnsControl;$$('[data-fault-kind]').forEach(b=>b.disabled=busy||!ready);$('#manual-control-status').textContent=rosOwnsControl?'ROS 실습에서 제어 중':!ready?'물리 연결 필요':canDrive?'수동 제어 가능':'임무 제어기 사용 중';}
function controllerRunning(c){return !!c.pid&&!['failed','exited','stopped','interrupted','not_started'].includes(c.status)}

async function loadDataset(id,index=0){if(!id)return;const generation=++S.datasetLoad;try{const d=await api(wb(`/datasets/${encodeURIComponent(id)}`));const f=d.frames|| (await api(wb(`/datasets/${encodeURIComponent(id)}/frames`))).frames;if(generation!==S.datasetLoad)return;S.datasetId=id;S.dataset=d;S.frames=f||[];S.dirty=false;$('#dataset-select').value=id;renderDataset();await loadFrame(Math.min(index,S.frames.length-1));if(d.frozen){if(!$('#train-dataset').value)$('#train-dataset').value=id;if(!$('#eval-dataset').value)$('#eval-dataset').value=id;}renderAvailability()}catch(e){flash(e.message,true)}}
function renderDataset(){const d=S.dataset;if(!d)return;$('#dataset-facts').innerHTML=`<span><strong>${d.count??S.frames.length}</strong> 장</span><span><strong>${d.positive_frames??'—'}</strong> 라벨 이미지</span><span>${d.episodes?.length??new Set(S.frames.map(f=>f.episode)).size}회차</span><span class="tag ${d.frozen?'good':''}">${d.frozen?'고정됨':d.status==='complete'?'편집 가능':labelForStatus(d.status)} · v${d.revision||1}</span>`;$('#freeze-dataset').textContent=d.frozen?'학습 데이터 고정됨':'학습용으로 고정';$('#annotation-class').innerHTML=(d.classes||classes).map((c,i)=>`<option value="${i}">${esc(classNames[c]||c)}</option>`).join('');$('#dataset-quality').innerHTML=`<h3>라벨 분포</h3>${(d.classes||classes).map((c,i)=>`<div class="class-count"><span>${esc(classNames[c]||c)}</span><strong>${d.class_counts?.[c]??d.class_counts?.[i]??0}</strong></div>`).join('')}<p class="small-note">${d.frozen?`분할: ${esc(JSON.stringify(d.split_counts||{}))}`:'라벨 확인 후 데이터 버전을 고정하세요.'}<br>${d.synthetic===true?'출처: 물리 시뮬레이터 합성 영상':d.synthetic===false?'출처: 가져온 이미지':`출처: ${esc(d.source||'확인 필요')}`}</p>`;}
async function loadFrame(index){if(index<0||!S.frames[index]){S.image=null;S.labels=[];$('#editor-empty').hidden=false;$('#frame-number').textContent='0 / 0';return;}const generation=++S.frameLoad;const frame=S.frames[index];try{const url=await imageURL(frame.image_url||wb(`/datasets/${S.datasetId}/frames/${frame.id}.jpg`));const image=await imageFrom(url);if(generation!==S.frameLoad)return;S.frameIndex=index;S.image=image;S.labels=structuredClone(frame.labels||[]);S.selectedBox=-1;S.dirty=false;const canvas=$('#label-canvas');canvas.width=frame.width||image.naturalWidth;canvas.height=frame.height||image.naturalHeight;$('#editor-empty').hidden=true;$('#frame-number').textContent=`${index+1} / ${S.frames.length}`;$('#frame-origin').textContent=`${frame.episode||'회차 미확인'} · ${frame.split||'미분할'}`;$('#frame-prev').disabled=index===0;$('#frame-next').disabled=index>=S.frames.length-1;renderAnnotations();drawLabels();renderThumbnails();}catch(e){flash(e.message,true)}}
function imageFrom(url){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('이미지를 디코딩하지 못했습니다.'));img.src=url})}
async function renderThumbnails(){const generation=S.frameLoad,container=$('#frame-thumbnails');const start=Math.max(0,Math.min(S.frameIndex-4,S.frames.length-10)),frames=S.frames.slice(start,start+10);container.innerHTML=frames.map((f,i)=>`<button class="frame-thumbnail ${start+i===S.frameIndex?'active':''}" data-frame-index="${start+i}" aria-label="${start+i+1}번 이미지"><span>${start+i+1}</span></button>`).join('');await Promise.allSettled(frames.map(async(f,i)=>{const url=await imageURL(f.image_url||wb(`/datasets/${S.datasetId}/frames/${f.id}.jpg`));if(generation!==S.frameLoad)return;const b=container.querySelector(`[data-frame-index="${start+i}"]`);if(b){const im=new Image();im.src=url;im.alt=`${start+i+1}번 이미지`;b.prepend(im)}}))}
function drawLabels(preview){const canvas=$('#label-canvas'),ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);if(!S.image)return;ctx.drawImage(S.image,0,0,w,h);const boxes=[...S.labels];if(preview)boxes.push(preview);boxes.forEach((label,i)=>{const [cx,cy,bw,bh]=label.bbox,x=(cx-bw/2)*w,y=(cy-bh/2)*h;const color=boxColors[label.class_id%boxColors.length];ctx.strokeStyle=color;ctx.lineWidth=i===S.selectedBox?4:2;ctx.fillStyle=color+'20';ctx.fillRect(x,y,bw*w,bh*h);ctx.strokeRect(x,y,bw*w,bh*h);ctx.font=`600 ${Math.max(12,Math.round(w/47))}px sans-serif`;const name=(S.dataset?.classes||classes)[label.class_id],text=`${i+1} ${classNames[name]||name}`;const tw=ctx.measureText(text).width+12;ctx.fillStyle=color;ctx.fillRect(x,Math.max(0,y-22),tw,22);ctx.fillStyle='#14202a';ctx.fillText(text,x+6,Math.max(15,y-6));if(i===S.selectedBox){ctx.fillStyle=color;for(const [px,py]of [[x,y],[x+bw*w,y],[x,y+bh*h],[x+bw*w,y+bh*h]])ctx.fillRect(px-4,py-4,8,8)}})}
function renderAnnotations(){const names=S.dataset?.classes||classes;$('#annotation-list').innerHTML=S.labels.length?S.labels.map((l,i)=>`<button class="annotation-row ${i===S.selectedBox?'active':''}" data-box-index="${i}" style="--label-color:${boxColors[l.class_id%boxColors.length]}"><i></i><span>${i+1}. ${esc(classNames[names[l.class_id]]||names[l.class_id])}</span><small>${Math.round(l.bbox[2]*100)} × ${Math.round(l.bbox[3]*100)}%</small></button>`).join(''):'<p class="muted">라벨 없음 · 물체가 없으면 빈 라벨로 유지합니다.</p>';$('#label-save-state').textContent=S.dataset?.frozen?'고정 버전 · 읽기 전용':S.dirty?'저장하지 않은 변경':'저장된 라벨';if(S.selectedBox>=0)$('#annotation-class').value=S.labels[S.selectedBox].class_id;renderAvailability()}
function editChanged(){S.dirty=true;renderAnnotations();drawLabels()}
async function saveLabels(){if(!S.dirty||!S.dataset||S.dataset.frozen)return;const frame=S.frames[S.frameIndex];await api(wb(`/datasets/${S.datasetId}/labels`),{method:'POST',body:{frame_id:frame.id,labels:S.labels}});frame.labels=structuredClone(S.labels);S.dirty=false;renderAnnotations();const manifest=await api(wb(`/datasets/${S.datasetId}`));S.dataset=manifest;renderDataset();flash('실제 라벨을 저장했습니다.');}
function point(event){const canvas=$('#label-canvas'),r=canvas.getBoundingClientRect();return {x:Math.max(0,Math.min(1,(event.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(event.clientY-r.top)/r.height))}}
const corners=b=>{const [x,y,w,h]=b;return [[x-w/2,y-h/2],[x+w/2,y-h/2],[x-w/2,y+h/2],[x+w/2,y+h/2]]};
$('#label-canvas').addEventListener('pointerdown',event=>{if(!S.image||S.dataset?.frozen||S.dataset?.status!=='complete')return;const p=point(event);event.currentTarget.setPointerCapture(event.pointerId);if(S.tool==='draw'){drag={kind:'draw',start:p,current:p};return;}let hit=-1,corner=-1;for(let i=S.labels.length-1;i>=0;i--){const cs=corners(S.labels[i].bbox);const c=cs.findIndex(([x,y])=>Math.hypot((x-p.x)*event.currentTarget.clientWidth,(y-p.y)*event.currentTarget.clientHeight)<12);const [x,y,w,h]=S.labels[i].bbox;if(c>=0||(p.x>=x-w/2&&p.x<=x+w/2&&p.y>=y-h/2&&p.y<=y+h/2)){hit=i;corner=c;break}}S.selectedBox=hit;drag=hit<0?null:{kind:corner>=0?'resize':'move',start:p,original:[...S.labels[hit].bbox],corner,index:hit};renderAnnotations();drawLabels()});
$('#label-canvas').addEventListener('pointermove',event=>{if(!drag)return;const p=point(event);drag.current=p;if(drag.kind==='draw'){const x=Math.min(p.x,drag.start.x),y=Math.min(p.y,drag.start.y),w=Math.abs(p.x-drag.start.x),h=Math.abs(p.y-drag.start.y);drawLabels({class_id:Number($('#annotation-class').value),bbox:[x+w/2,y+h/2,w,h]});return;}let [x,y,w,h]=drag.original;if(drag.kind==='move'){x=Math.min(1-w/2,Math.max(w/2,x+p.x-drag.start.x));y=Math.min(1-h/2,Math.max(h/2,y+p.y-drag.start.y));}else{const cs=corners(drag.original),opposite=cs[3-drag.corner],left=Math.min(p.x,opposite[0]),top=Math.min(p.y,opposite[1]);w=Math.max(.005,Math.abs(p.x-opposite[0]));h=Math.max(.005,Math.abs(p.y-opposite[1]));x=Math.max(w/2,Math.min(1-w/2,left+w/2));y=Math.max(h/2,Math.min(1-h/2,top+h/2));}S.labels[drag.index].bbox=[x,y,w,h];S.dirty=true;drawLabels()});
function endDrag(event){if(!drag)return;if(drag.kind==='draw'){const p=drag.current||point(event),w=Math.abs(p.x-drag.start.x),h=Math.abs(p.y-drag.start.y);if(w*$('#label-canvas').width>=4&&h*$('#label-canvas').height>=4){S.labels.push({class_id:Number($('#annotation-class').value),bbox:[(p.x+drag.start.x)/2,(p.y+drag.start.y)/2,w,h]});S.selectedBox=S.labels.length-1;S.dirty=true;}}drag=null;renderAnnotations();drawLabels()}
$('#label-canvas').addEventListener('pointerup',endDrag);$('#label-canvas').addEventListener('pointercancel',()=>{drag=null;drawLabels()});

function progressHTML(job,logs=false){const p=job.progress||{},completed=p.completed??p.epoch,total=p.total??p.epochs,value=Number(total)>0?Math.min(100,Math.max(0,Number(completed||0)/Number(total)*100)):null;const unit={images:'장',epochs:'epoch',batches:'batch',steps:'단계',splits:'데이터 분할',jobs:'작업'}[p.unit]||p.unit||'';const elapsed=p.elapsed_seconds??(job.started_at?(job.finished_at||Date.now()/1000)-job.started_at:null);const loss=typeof p.loss==='object'?Object.entries(p.loss).map(([k,v])=>`${k}: ${fmt(v,4)}`).join(' · '):p.loss;return `<div class="progress-heading"><strong>${value==null?'진행 확인 중':fmt(value,0)+'%'}</strong><span>${esc(completed??'—')} / ${esc(total??'—')} ${esc(unit)}</span></div><div class="progress-track"><i style="width:${value??0}%"></i></div><div class="progress-values"><div><span>작업 상태</span><strong>${esc(labelForStatus(job.status))}${p.stage?' · '+esc(stageNames[p.stage]||p.stage):''}</strong></div><div><span>실제 경과</span><strong>${elapsed==null?'서버 기록 대기':fmt(elapsed,1)+'초'}</strong></div>${p.epoch!=null?`<div><span>epoch</span><strong>${job.status==='succeeded'?'완료':esc(p.epoch)} / ${esc(p.epochs??total??'—')}</strong></div>`:''}${loss!=null?`<div><span>손실값</span><strong>${esc(loss)}</strong></div>`:''}</div>${job.error?`<p class="job-error">${esc(job.error)}</p>`:''}${logs?`<details class="progress-log" data-log-job="${esc(job.id)}" ${openProgressLogs.has(job.id)?'open':''}><summary>상세 실행 로그</summary><pre class="log-view">${esc((job.logs||[]).slice(-35).join('\n')||'아직 프로세스 출력이 없습니다.')}</pre></details>`:''}${!terminal.has(job.status)?`<button class="button quiet" data-cancel-job="${esc(job.id)}">작업 중단</button>`:''}`}
function renderJobs(jobs){$('#job-list').innerHTML=jobs.length?jobs.map(j=>{const p=j.progress||{};return `<div class="job-row"><span class="job-kind">${esc(kindNames[j.kind]||j.kind)}</span><span class="job-name">${esc(j.settings?.name||j.id)}</span><span class="tag ${statusClass(j.status)}">${esc(labelForStatus(j.status))}</span><span class="job-mini-progress">${p.completed??'—'} / ${p.total??'—'}</span><button class="button quiet" data-open-job="${esc(j.id)}">상세</button>${!terminal.has(j.status)?`<button class="button quiet" data-cancel-job="${esc(j.id)}">중단</button>`:''}</div>`}).join(''):'<p class="muted">아직 작업이 없습니다.</p>';}
function renderJobDialog(job){$('#job-dialog-title').textContent=kindNames[job.kind]||job.kind;$('#job-dialog-content').innerHTML=progressHTML(job,true)}
function metricsFor(model){const raw=model?.metrics?.test||model?.metrics||{};return {map50:raw.map50??raw['metrics/mAP50(B)']??raw.mAP50,precision:raw.precision??raw['metrics/precision(B)'],recall:raw.recall??raw['metrics/recall(B)'],map:raw.map??raw['metrics/mAP50-95(B)']}}
function qualityText(m){const q=m?.quality?.status;return q==='measured_zero'?'측정 결과 0 · 성능 개선 필요':q==='measured'?'시험셋 측정됨':q==='unvalidated'?'평가 전':q||'품질 상태 확인 필요'}
async function selectModel(id){S.modelId=id;$('#eval-model').value=id;$('#deploy-model').value=id;await loadModel(id);renderAvailability()}
async function loadModel(id){if(!id)return;const generation=++S.modelLoad;try{const model=await api(wb(`/models/${encodeURIComponent(id)}`));if(generation!==S.modelLoad)return;S.modelDetail=model;renderModel(model)}catch(e){flash(e.message,true)}}
function renderModel(m){const metric=metricsFor(m);$('#evaluation-summary').innerHTML=[['mAP50 · 시험셋',percent(metric.map50)],['정밀도',percent(metric.precision)],['재현율',percent(metric.recall)],['평가 상태',qualityText(m)]].map(([name,value],i)=>`<div class="metric"><span>${esc(name)}</span><strong class="${i===3?'metric-word':''}">${esc(value)}</strong></div>`).join('');let per=m.per_class?.test||m.per_class||[];if(!Array.isArray(per))per=Object.entries(per).map(([name,v])=>({name,...(typeof v==='object'?v:{map50:v})}));$('#per-class-results').innerHTML=per.length?`<table class="data-table"><thead><tr><th>물체</th><th>정밀도</th><th>재현율</th><th>mAP50</th></tr></thead><tbody>${per.map(x=>`<tr><td>${esc(classNames[x.name||x.class_name]||x.name||x.class_name||x.class_id)}</td><td>${percent(x.precision)}</td><td>${percent(x.recall)}</td><td>${percent(x.map50??x.AP50)}</td></tr>`).join('')}</tbody></table>`:'<p class="muted">아직 종류별 평가값이 없습니다.</p>';$('#model-provenance').innerHTML=pairs([['모델',m.name||m.id],['데이터 버전',m.dataset_id],['가중치 SHA',m.weights_sha256],['데이터 SHA',m.dataset_sha256],['학습 장치',m.settings?.device],['학습 횟수',m.settings?.epochs],['품질',qualityText(m)],['새 원본 사진 평가',m.source_audit?.independent_source_test?'원본 그룹 분리됨':'미검증 · 예시 사진 공유 또는 출처 미등록']]);$('#deploy-quality').hidden=false;$('#deploy-quality').textContent=`${qualityText(m)} · 시험 mAP50 ${percent(metric.map50)}. 실제 카메라 성능은 별도 검증이 필요합니다.`;renderModelGallery(m);}
function pairs(items){return `<dl class="detail-pairs">${items.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd class="${k.includes('SHA')?'hash':''}">${esc(v??'—')}</dd></div>`).join('')}</dl>`}
async function renderModelGallery(m){const items=[...(m.samples||[]).slice(0,12).map((s,i)=>({name:s.name||s.id||`시험 이미지 ${i+1}`,image_url:s.prediction_url||s.image_url})),...(m.plots||[]).map(p=>typeof p==='string'?{name:p,image_url:p}:p)].filter(i=>i.image_url);const target=$('#evaluation-gallery');target.innerHTML=items.length?items.map((x,i)=>`<figure data-gallery="${i}"><figcaption>${esc(x.name||'평가 결과')}</figcaption></figure>`).join(''):'<p class="muted">아직 생성된 평가 이미지가 없습니다.</p>';await Promise.allSettled(items.map(async(x,i)=>{const url=await imageURL(x.image_url);if(S.modelDetail?.id!==m.id)return;const f=target.querySelector(`[data-gallery="${i}"]`);if(f){const im=new Image();im.alt=x.name||'실제 평가 결과';im.src=url;f.prepend(im)}}))}
function renderDeployment(){const d=S.summary?.deployment,c=S.summary?.controller||{};$('#deployment-tag').textContent=c.loaded?'가중치 읽기 확인':d?'파일 준비됨':'미적용';$('#deployment-tag').className=`tag ${c.loaded?'good':d?'warn':''}`;if(!d)return;const matched=!!c.loaded&&c.weights_sha256===d.weights_sha256;$('#deployment-detail').innerHTML=`<ul class="deploy-checks"><li class="good"><i>✓</i><div>모델 파일 복사·해시 확인<small>${esc(d.model_id)}</small></div></li><li class="${controllerRunning(c)?'good':''}"><i>${controllerRunning(c)?'✓':'○'}</i><div>로봇 프로세스 실행<small>${esc(labelForStatus(c.status))}${c.pid?` · PID ${c.pid}`:''}</small></div></li><li class="${matched?'good':''}"><i>${matched?'✓':'○'}</i><div>동일 가중치 로드·첫 추론 확인<small>${matched?esc(c.weights_sha256):'실행 후 확인합니다.'}</small></div></li></ul>${pairs([['환경',d.mode],['정책',d.policy==='observe'?'관측만':'임무 수행'],['코드 버전',d.code_name||d.code_version_id||'기존 예제'],['코드 SHA',String(c.code_sha256||d.code_sha256||'').slice(0,12)||'미확인'],['실행 파일',c.code_path||'실행 전'],['프레임',c.frame_seq||'아직 없음']])}${c.error?`<p class="notice error">${esc(c.error)}</p>`:''}`;}
function renderController(c){$('#controller-state-tag').textContent=labelForStatus(c.status);$('#controller-state-tag').className=`tag ${c.loaded?'good':statusClass(c.status)}`;$('#controller-logs').textContent=(c.logs||[]).slice(-40).join('\n')||'아직 실행 기록이 없습니다.';const o=c.observations||{};$('#runtime-observations').textContent=Object.keys(o).length?JSON.stringify(o,null,2):'아직 인식·임무 관측이 없습니다.';}

async function ensureScene(){if(S.scene)return S.scene;if(scenePromise)return scenePromise;scenePromise=import('/arena.js').then(({ArenaScene})=>{S.scene=new ArenaScene($('#arena-viewport'),slot=>S.scene?.select(slot));if(S.snapshot&&physicsReady())S.scene.update(S.snapshot);renderPhysics();return S.scene}).catch(e=>{scenePromise=null;$('#arena-unavailable').hidden=false;$('#arena-unavailable').innerHTML=`<h3>3D 표시를 시작하지 못했습니다.</h3><p>${esc(e.message)}</p>`;return null});return scenePromise}
async function refreshRuntime(){if(!S.key)return;const mode=S.runtime;try{const snapshot=await api(admin('state'));if(mode!==S.runtime)return;S.snapshot=snapshot;if(S.page==='run'){await ensureScene();S.scene?.update(snapshot);renderMatch(snapshot);renderRunNotice();renderRobots(snapshot.robots||[]);renderFaults(snapshot.robots?.find(r=>r.slot==='B-1'));}const team=S.teams.find(t=>t.slot==='B-1');if(team&&S.page==='run'){const own=await api(`${robot('state')}?mission_code=${encodeURIComponent(team.mission_code)}`,{auth:false});if(mode===S.runtime)renderSensor(own);}}catch(e){if(S.page==='run')$('#sensor-freshness').textContent=`수신 오류: ${e.message}`}}
async function runtimeLoop(){clearTimeout(runtimeTimer);try{if(S.page==='run')await refreshRuntime()}finally{runtimeTimer=setTimeout(runtimeLoop,500)}}
function renderMatch(s){$('#opponent-difficulty').value=String(s.difficulty??0);$('#opponent-difficulty').disabled=['running','reporting'].includes(s.phase)||S.busy.size>0;const practice=S.runtime==='practice';const names={idle:'준비 전',ready:'준비 단계',running:'경기 진행',reporting:'결과 보고',finished:'경기 종료'};$('#match-phase').textContent=practice?(s.paused?'자유연습 · 일시정지':'자유연습 · 진행 중'):s.countdown_remaining>0?`시작까지 ${Math.ceil(s.countdown_remaining)}초`:s.paused&&['running','reporting'].includes(s.phase)?'일시정지':names[s.phase]||s.phase;const show={prepare:!practice&&['idle','finished'].includes(s.phase),start:!practice&&s.phase==='ready'&&!s.countdown_remaining,pause:(practice||s.phase==='running')&&!s.paused,resume:s.paused&&(practice||s.phase==='running'),finish:practice||['running','reporting'].includes(s.phase)};$('#match-finish').textContent=practice?'자유연습 종료':'경기 종료';$$('[data-match-action]').forEach(b=>{b.hidden=!show[b.dataset.matchAction];b.disabled=S.busy.size>0||!physicsReady()});}
function renderRobots(robots){const focused=document.activeElement?.closest('#runtime-robots');if(focused)return;$('#runtime-robots').innerHTML=robots.map(r=>`<div class="runtime-robot ${String(r.camp).startsWith('R')?'red':''}"><strong>${esc(r.slot)}${r.slot==='B-1'?' · 내 로봇':''}</strong><p>HP ${r.hp}/4 · 탄약 ${r.ammo} · ${r.strategy==='external'?'외부 제어 대기/실행':'전체 상태를 사용하는 시연 정책'}</p>${r.slot==='B-1'?'<p>적용한 인식 모델 또는 수동 제어를 사용합니다.</p>':`<label>시연 정책<select data-opponent-slot="${esc(r.slot)}">${[['external','정지 · 외부 제어'],['scout','시연 · 정찰'],['defender','시연 · 방어'],['hunter','시연 · 추적'],['capturer','시연 · 거점'],['balanced','시연 · 균형']].map(([v,n])=>`<option value="${v}" ${r.strategy===v?'selected':''}>${n}</option>`).join('')}</select></label>`}</div>`).join('')}
function renderSensor(r){S.ownSensor=r;$('#sensor-freshness').textContent='현재 센서 수신';$('#sensor-freshness').className='tag good';$('#sensor-metrics').innerHTML=[['HP',`${r.hp} / ${r.hp_max||4}`],['탄약',r.ammo],['배터리',`${r.battery_pct??'—'}%`],['상태',r.cmd],['출발점 x',`${fmt(r.odom?.x)} m`],['출발점 y',`${fmt(r.odom?.y)} m`],['방향',`${fmt((r.odom?.yaw||0)*180/Math.PI,0)}°`],['카메라',r.camera_available?'수신 가능':'장애'],['pan',`${fmt(r.pan,1)} · ${fmt((r.pan||0)*.5,1)}°`],['tilt',`${fmt(r.tilt,1)} · ${fmt((r.tilt||0)*.15,1)}°`],['레이저',r.laser?'발광 중':'꺼짐'],['IMU yaw',`${fmt((r.imu?.yaw||0)*180/Math.PI,1)}°`]].map(([k,v])=>`<div><span>${esc(k)}</span><strong>${esc(v??'—')}</strong></div>`).join('');const canvas=$('#scan-canvas'),ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height;ctx.fillStyle='#101d25';ctx.fillRect(0,0,w,h);const scale=Math.min(w/2,h/2)/3.2,cx=w/2,cy=h/2;ctx.strokeStyle='#2e4c5c';ctx.lineWidth=1;for(const meters of [1,2,3]){ctx.beginPath();ctx.arc(cx,cy,meters*scale,0,Math.PI*2);ctx.stroke()}ctx.strokeStyle='#426275';ctx.beginPath();ctx.moveTo(cx,0);ctx.lineTo(cx,h);ctx.moveTo(0,cy);ctx.lineTo(w,cy);ctx.stroke();ctx.fillStyle='#91c9b5';(r.scan?.ranges||[]).forEach((dist,i)=>{const angle=(r.scan.angle_min||0)+i*(r.scan.angle_increment||0),d=Math.min(3.2,Number(dist)||0);const x=cx-Math.sin(angle)*d*scale,y=cy-Math.cos(angle)*d*scale;ctx.fillRect(x-1.5,y-1.5,3,3)});ctx.fillStyle='#e2c477';ctx.beginPath();ctx.moveTo(cx,cy-8);ctx.lineTo(cx-6,cy+6);ctx.lineTo(cx+6,cy+6);ctx.closePath();ctx.fill();ctx.font='12px sans-serif';ctx.fillStyle='#81a5b7';ctx.fillText('라이다 · 전방 ↑ · 반경 3 m',12,20)}
async function refreshCameras(){if(cameraBusy||S.page!=='run'||!physicsReady()||document.hidden)return;const team=S.teams.find(t=>t.slot==='B-1');if(!team)return;cameraBusy=true;const mode=S.runtime;try{const c=await api(wb('/controller'));if(mode!==S.runtime)return;if(c.loaded&&c.frame_seq){let synchronized=false;for(let attempt=0;attempt<2;attempt++){const current=attempt===0?c:await api(wb('/controller'));const res=await response(wb('/controller/frame.jpg'));const seq=Number(res.headers.get('X-Frame-Seq')),hash=res.headers.get('X-Image-Sha256');if(seq!==Number(current.frame_seq)||!hash||hash!==current.image_sha256)continue;const bytes=await res.arrayBuffer();const actual=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),v=>v.toString(16).padStart(2,'0')).join('');if(hash!==actual)continue;const url=URL.createObjectURL(new Blob([bytes],{type:'image/jpeg'}));try{const image=await imageFrom(url);if(mode!==S.runtime)return;drawInference(image,current.predictions||[]);$('#ugv-frame-status').textContent=`프레임 ${seq}`;$('#ugv-frame-status').className='tag good';$('#prediction-summary').textContent=`동일 프레임 검출 ${(current.predictions||[]).length}개 · ${current.inference_ms!=null?fmt(current.inference_ms,0)+' ms · ':''}가중치 ${String(current.weights_sha256||'').slice(0,10)}`;$('#ugv-camera-empty').hidden=true;synchronized=true;}finally{URL.revokeObjectURL(url)}break;}if(!synchronized){$('#ugv-frame-status').textContent='프레임 동기화 중';$('#prediction-summary').textContent='이미지와 예측의 프레임 번호·해시가 일치할 때만 표시합니다.';}}
    else{const res=await response(`${robot('camera')}?mission_code=${encodeURIComponent(team.mission_code)}`,{auth:false});const url=URL.createObjectURL(await res.blob());try{const image=await imageFrom(url);if(mode!==S.runtime)return;drawInference(image,[]);$('#ugv-camera-empty').hidden=true;$('#ugv-frame-status').textContent='원본 센서 영상';$('#ugv-frame-status').className='tag';$('#prediction-summary').textContent='인식 모델 미실행 · 검출 상자를 표시하지 않습니다.';}finally{URL.revokeObjectURL(url)}}
  }catch(e){$('#ugv-frame-status').textContent='영상 수신 대기';$('#ugv-camera-empty').hidden=false;$('#ugv-camera-empty').textContent=e.message;}finally{cameraBusy=false}
  try{const suffix=S.runtime==='mission'?'':'&camera=test1';const res=await response(`/api/report/drone?mission_code=${encodeURIComponent(team.mission_code)}${suffix}`,{auth:false});const captured=res.headers.get('X-Captured-At'),interval=res.headers.get('X-Frame-Interval-S'),url=URL.createObjectURL(await res.blob());if(mode!==S.runtime){URL.revokeObjectURL(url);return;}const old=droneUrl;droneUrl=url;$('#drone-image').src=url;$('#drone-image').hidden=false;$('#drone-camera-empty').hidden=true;$('#drone-frame-status').textContent=`${interval||'—'}초 간격`;$('#drone-camera-caption').textContent=`캡처 ${captured||'확인 불가'} · ${res.headers.get('X-Camera')||'고정 UAV'}`;if(old)URL.revokeObjectURL(old);}catch(e){$('#drone-camera-empty').hidden=false;$('#drone-camera-empty').textContent=e.status===403?'표적 파괴에 따라 UAV 영상이 중단됐습니다.':e.message;$('#drone-frame-status').textContent=e.status===403?'영상 중단':'수신 대기';}}
function drawInference(image,predictions){const canvas=$('#inference-canvas');canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;const ctx=canvas.getContext('2d');ctx.drawImage(image,0,0);for(const p of predictions){const box=p.xyxy;if(!Array.isArray(box)||box.length!==4)continue;const [x1,y1,x2,y2]=box,color=boxColors[(p.class_id||0)%boxColors.length];ctx.strokeStyle=color;ctx.lineWidth=2;ctx.strokeRect(x1,y1,x2-x1,y2-y1);const verified=p.photo?.accepted,name=verified?p.photo.type:(p.class_name||p.name||classes[p.class_id]),text=verified?`${classNames[name]||name} · 사진 확인 ${fmt(p.photo.score,2)}`:`${classNames[name]||name} ${percent(p.confidence)}${p.photo?' · 집계 제외':''}`;ctx.font='13px sans-serif';const width=ctx.measureText(text).width+10;ctx.fillStyle=color;ctx.fillRect(x1,Math.max(0,y1-20),width,20);ctx.fillStyle='#13212a';ctx.fillText(text,x1+5,Math.max(14,y1-5))}}
async function cameraLoop(){clearTimeout(cameraTimer);try{await refreshCameras()}finally{cameraTimer=setTimeout(cameraLoop,700)}}
async function startPhysics(){const p=await api('/api/physics/control',{method:'POST',body:{action:'start',runtime:S.runtime}});S.physics=p;flash('물리 시뮬레이터 시작을 요청했습니다. 연결 상태를 확인합니다.');if(S.runtime!=='mission')await api('/api/admin/control',{method:'POST',body:{action:'camera',enabled:true,test_mode:true}});await refreshStatus();}
let driveToken=0,driveDirection=null;
async function startDrive(direction){if(direction==='stop'){stopDrive(true);return;}if(!physicsReady())return;const c=S.summary?.controller||{};if(controllerRunning(c)&&S.summary?.deployment?.policy!=='observe')return;const token=++driveToken;driveDirection=direction;const team=S.teams.find(t=>t.slot==='B-1');if(!team)return;try{await api(robot('strategy'),{method:'POST',auth:false,body:{mission_code:team.mission_code,strategy:'external'}});if(token!==driveToken)return;const tick=async()=>{if(token!==driveToken||driveSending)return;driveSending=true;try{const command={forward:[.12,0],back:[-.12,0],left:[0,.55],right:[0,-.55]}[direction];await api(robot('cmd_vel'),{method:'POST',auth:false,body:{mission_code:team.mission_code,linear_x:command[0],angular_z:command[1]}})}catch(e){flash(e.message,true);stopDrive()}finally{driveSending=false}};await tick();if(token===driveToken)driveTimer=setInterval(tick,100)}catch(e){flash(e.message,true);stopDrive()}}
function stopDrive(force=false){const wasActive=!!driveDirection||!!driveTimer;driveToken++;driveDirection=null;clearInterval(driveTimer);driveTimer=null;if(!wasActive&&force!==true)return;const team=S.teams.find(t=>t.slot==='B-1');if(team&&S.key)api(robot('cmd_vel'),{method:'POST',auth:false,body:{mission_code:team.mission_code,linear_x:0,angular_z:0}}).catch(()=>{});}
async function importFiles(files){const images=files.filter(f=>/\.(jpe?g|png)$/i.test(f.name));if(!images.length)throw new Error('JPG 또는 PNG 사진을 선택하세요.');if(images.reduce((n,f)=>n+f.size,0)>22*1024*1024)throw new Error('한 번에 가져오는 원본 이미지 합계는 22 MiB 이하로 나누세요. JSON 요청은 32 MiB를 넘을 수 없습니다.');const texts=new Map();for(const f of files.filter(f=>/\.txt$/i.test(f.name)))texts.set((f.webkitRelativePath||f.name).replace(/\.txt$/i,''),await f.text());let provenance={};const provenanceFile=files.find(f=>f.name==='provenance.json');if(provenanceFile)provenance=JSON.parse(await provenanceFile.text());const records=[];for(const f of images){const path=f.webkitRelativePath||f.name,stem=path.replace(/\.(jpe?g|png)$/i,''),text=texts.get(stem)||'';const labels=text.split(/\r?\n/).filter(x=>x.trim()).map((line,i)=>{const values=line.trim().split(/\s+/).map(Number);if(values.length!==5||values.some(x=>!Number.isFinite(x)))throw new Error(`${f.name}의 ${i+1}번째 라벨 형식이 올바르지 않습니다.`);return {class_id:values[0],bbox:values.slice(1)}});const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(f)});const parent=path.includes('/')?path.split('/').slice(0,-1).join('/'):'import-session';records.push({name:f.name,image_base64:data,labels,episode:provenance[f.name]?.episode||parent,source_group:provenance[f.name]?.source_group||null});}const result=await api(wb('/datasets/import'),{method:'POST',body:{name:$('#collect-name').value.trim()||'가져온 사진',classes,files:records}});await refreshStatus();await loadDataset(result.id);flash(`${images.length}장을 가져왔습니다. 실제 촬영 회차 ${new Set(records.map(x=>x.episode)).size}개를 확인하세요.`);}

