$('#gimbal-send').addEventListener('click',()=>act('gimbal',$('#gimbal-send'),async()=>{const reply=await manualCommand('gimbal',{pan:Number($('#gimbal-pan').value),tilt:Number($('#gimbal-tilt').value),speed:Number($('#gimbal-speed').value),acc:Number($('#gimbal-acc').value)});$('#gimbal-response').textContent=reply.message==='ok'?'명령 접수 확인. 실제 pan·tilt 값은 센서에서 확인하세요.':`서버 응답: ${reply.message||JSON.stringify(reply)}`;$('#gimbal-response').classList.toggle('error',reply.message==='locked');}));
$('#fire-button').addEventListener('click',()=>act('fire',$('#fire-button'),async()=>{const reply=await manualCommand('fire',{}),names={fired:'발사 접수 · 5초 발광',empty:'탄약 없음',locked:'발사 잠금',reloading:'재발사 대기'};$('#fire-response').textContent=`${names[reply.message]||reply.message||'응답 확인'}${reply.left_ms!=null?' · 남은 대기 '+fmt(reply.left_ms/1000,1)+'초':''}`;$('#fire-response').classList.toggle('error',reply.message==='empty'||reply.message==='locked');}));
$('#oled-send').addEventListener('click',()=>act('oled',$('#oled-send'),async()=>{const text=$('#oled-text').value;if(!/^[\x20-\x7E]{0,21}$/.test(text))throw new Error('OLED에는 영문·숫자·기호를 최대 21자까지 보낼 수 있습니다.');const reply=await manualCommand('oled',{line:Number($('#oled-line').value),text});$('#oled-response').textContent=reply.accepted?`${Number($('#oled-line').value)+1}번째 줄 표시 요청이 서버에 접수됐습니다. 10초 뒤 기본 화면으로 돌아갑니다.`:JSON.stringify(reply);}));
$$('[data-fault-kind]').forEach(button=>button.addEventListener('click',()=>act('fault',button,async()=>{const kind=button.dataset.faultKind,enabled=button.getAttribute('aria-pressed')!=='true';await api(admin('control'),{method:'POST',body:{action:'fault',slot:'B-1',kind,enabled}});await refreshRuntime();$('#fault-response').textContent=`${{camera:'카메라',lidar:'라이다',network:'UGV 통신'}[kind]} 장애 ${enabled?'주입':'해제'} 요청 후 서버 상태를 다시 읽었습니다.`;})));
development=createDevelopment({api,response,flash,refreshStatus,switchPage,state:()=>S,refreshAvailability:renderAvailability});
const runNotice=document.createElement('section');runNotice.id='run-notice';runNotice.className='notice neutral';runNotice.setAttribute('role','status');$('#page-run .page-title').after(runNotice);
recording=createRecording({api,response,flash,ensureScene,state:()=>S});
trainingOptions=createTrainingOptions({api,flash,refreshStatus,loadDataset,state:()=>S});
$$('[data-match-action]').forEach(b=>b.hidden=true);$('#annotation-class').innerHTML=classes.map((c,i)=>`<option value="${i}">${classNames[c]}</option>`).join('');window.addEventListener('popstate',()=>switchPage(new URLSearchParams(location.search).get('page')||'develop',false));switchPage(new URLSearchParams(location.search).get('page')||'develop',false);initialize();

async function stopSession(){
  if(stoppingSession)return;stoppingSession=true;renderAvailability();$('#match-phase').textContent='전체 정지 중…';stopDrive(true);
  const videoSave=recording?.stop('session_stopped');
  try{
    const result=await api('/api/development/stop',{method:'POST',body:{},signal:AbortSignal.timeout(60000)});
    S.physics=result.physics;S.snapshot=null;$('#match-phase').textContent='종료됨';
    await refreshStatus();development?.enter();flash('로봇·ROS 실습·경기장을 모두 종료했습니다.');
  }catch(error){flash(error.message,true);}
  finally{stoppingSession=false;renderAvailability();await videoSave;}
}

document.addEventListener('toggle',event=>{const el=event.target;if(el.matches?.('details[data-log-job]')){if(el.open)openProgressLogs.add(el.dataset.logJob);else openProgressLogs.delete(el.dataset.logJob);}},true);

function renderRunNotice(){
 const el=$('#run-notice');if(!el)return;
 const notice=describeRunState({physics:S.physics,controller:S.summary?.controller,deployment:S.summary?.deployment,runtime:S.runtime,snapshot:S.snapshot});
 el.className='notice '+(['code','error','paused'].includes(notice.kind)?'warn':'neutral');
 el.innerHTML=`<strong>${esc(notice.title)}</strong><p>${esc(notice.body)}</p>`;
}

$('#opponent-difficulty').addEventListener('change',()=>act('difficulty',$('#opponent-difficulty'),async()=>{await api(admin('control'),{method:'POST',body:{action:'difficulty',value:Number($('#opponent-difficulty').value)}});flash('다른 5대의 난이도를 변경했습니다. 속도·체력·채점은 그대로입니다.');await refreshRuntime();}));
